import React from "react";
import { useNavigate } from "react-router-dom";

function DoctorCard({ doctor }) {
    const navigate = useNavigate();

    return (
        <div
            style={styles.card}
            onMouseEnter={(e) =>
                (e.currentTarget.style.transform = "scale(1.02)")
            }
            onMouseLeave={(e) =>
                (e.currentTarget.style.transform = "scale(1)")
            }
        >
            {/* Left Image */}
            <img src={doctor.image} alt="doctor" style={styles.image} />

            {/* Right Content */}
            <div style={styles.info}>
                <h3 style={styles.name}>{doctor.name}</h3>
                <p style={styles.specialization}>{doctor.specialization}</p>

                <p style={styles.experience}>⭐ 4.5 • 10+ years experience</p>

                <button
                    style={styles.button}
                    onClick={() => navigate(`/book/${doctor.id}`)}
                >
                    Book Appointment
                </button>
            </div>
        </div>
    );
}

const styles = {
    card: {
        display: "flex",
        gap: "20px",
        padding: "15px",
        margin: "15px auto",
        width: "60%",
        background: "#fff",
        borderRadius: "10px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
        transition: "0.3s",
        cursor: "pointer",
    },
    image: {
        width: "100px",
        height: "100px",
        borderRadius: "50%",
        objectFit: "cover",
    },
    info: {
        flex: 1,
    },
    name: {
        margin: "0",
        color: "#1976d2",
    },
    specialization: {
        margin: "5px 0",
        color: "#555",
    },
    experience: {
        fontSize: "14px",
        color: "#888",
    },
    button: {
        marginTop: "10px",
        padding: "8px 15px",
        background: "#1976d2",
        color: "#fff",
        border: "none",
        borderRadius: "5px",
        cursor: "pointer",
    },
};

export default DoctorCard;
